parameterdescription.para:
使用率 Example WOLFSSL_BIGNUMr,a,p,m;
intret;
//setbignumbervalues
ret=wolfSSL_BN_mod_exp(r,a,p,m,NULL);
//checkretvalue

simplesect.para:
pointer DES EDE3操作のためのwolfssl_evp_cipherポインタを返します。 Example printf("blocksizedesede3cbc=%d\n",
wolfSSL_EVP_CIPHER_block_size(wolfSSL_EVP_des_ede3_cbc()));
printf("blocksizedesede3ecb=%d\n",
wolfSSL_EVP_CIPHER_block_size(wolfSSL_EVP_des_ede3_ecb()));

pointer DES操作のためのwolfssl_evp_cipherポインタを返します。 Example WOLFSSL_EVP_CIPHER*cipher;
cipher=wolfSSL_EVP_des_cbc();
…

parameterdescription.para:
SHAなどのハッシュの種類。 Example WOLFSSL_EVP_MD_CTX*md=NULL;
wolfCrypt_Init();
md=wolfSSL_EVP_MD_CTX_new();
if(md==NULL){
printf("errorsettingmd\n");
return-1;
}
printf("ciphermdinitret=%d\n",wolfSSL_EVP_DigestInit_ex(md,
wolfSSL_EVP_sha1(),e));
//freeresources

アルゴリズムで必要な場合はIV。 Example WOLFSSL_EVP_CIPHER_CTX*ctx=NULL;
WOLFSSL_ENGINE*e=NULL;
unsignedcharkey[16];
unsignedchariv[12];
wolfCrypt_Init();
ctx=wolfSSL_EVP_CIPHER_CTX_new();
if(ctx==NULL){
printf("issuecreatingctx\n");
return-1;
}

printf("cipherinitexerrorret=%d\n",wolfSSL_EVP_CipherInit_ex(NULL,
EVP_aes_128_cbc(),e,key,iv,1));
printf("cipherinitexsuccessret=%d\n",wolfSSL_EVP_CipherInit_ex(ctx,
EVP_aes_128_cbc(),e,key,iv,1));
//freeresources

使用する鍵 Example WOLFSSL_EVP_CIPHER_CTX*ctx=NULL;
wolfCrypt_Init();
ctx=wolfSSL_EVP_CIPHER_CTX_new();
if(ctx==NULL){
printf("errorsettingctx\n");
return-1;
}
printf("cipherctxinitret=%d\n",wolfSSL_EVP_EncryptInit_ex(ctx,
wolfSSL_EVP_aes_128_cbc(),e,key,iv));
//freeresources

アルゴリズムで必要な場合はIV。 Example WOLFSSL_EVP_CIPHER_CTX*ctx=NULL;
WOLFSSL_ENGINE*e=NULL;
unsignedcharkey[16];
unsignedchariv[12];

wolfCrypt_Init();

ctx=wolfSSL_EVP_CIPHER_CTX_new();
if(ctx==NULL){
printf("issuecreatingctx\n");
return-1;
}

printf("cipherinitexerrorret=%d\n",wolfSSL_EVP_DecryptInit_ex(NULL,
EVP_aes_128_cbc(),e,key,iv,1));
printf("cipherinitexsuccessret=%d\n",wolfSSL_EVP_DecryptInit_ex(ctx,
EVP_aes_128_cbc(),e,key,iv,1));
//freeresources

操作を実行するためのバッファー。 Example WOLFSSL_EVP_CIPHER_CTX*ctx=NULL;
unsignedcharout[100];
intoutl;
unsignedcharin[100];
intinl=100;

ctx=wolfSSL_EVP_CIPHER_CTX_new();
//setupctx
ret=wolfSSL_EVP_CipherUpdate(ctx,out,outl,in,inl);
//checkretvalue
//bufferoutholdsoutlbytesofdata
//freeresources

最後の復号化/暗号化のためのバッファ。 Example WOLFSSL_EVP_CIPHER_CTX*ctx;
intout1;
unsignedcharout[64];
//createctx
wolfSSL_EVP_CipherFinal(ctx,out,&out1);

キーの長さを設定する構造 Example WOLFSSL_EVP_CIPHER_CTX*ctx;
intkeylen;
//createctx
wolfSSL_EVP_CIPHER_CTX_set_key_length(ctx,keylen);

simplesect.para:
size ctx-> block_sizeを返します。 Example constWOLFSSL_CVP_CIPHER_CTX*ctx;
//setupctx
printf(“blocksize=%d\n”,wolfSSL_EVP_CIPHER_CTX_block_size(ctx));

parameterdescription.para:
フラグを設定する構造 Example WOLFSSL_EVP_CIPHER_CTX*ctx;
intflag;
//createctx
wolfSSL_EVP_CIPHER_CTX_set_flags(ctx,flag);

フラグをクリアするための構造 Example WOLFSSL_EVP_CIPHER_CTX*ctx;
intflag;
//createctx
wolfSSL_EVP_CIPHER_CTX_clear_flags(ctx,flag);

パディングフラグを設定する構造 Example WOLFSSL_EVP_CIPHER_CTX*ctx;
//createctx
wolfSSL_EVP_CIPHER_CTX_set_padding(ctx,1);

simplesect.para:
unsigned フラグ/モードの長い。 Example WOLFSSL_EVP_CIPHER_CTX*ctx;
unsignedlongflags;
ctx=wolfSSL_EVP_CIPHER_CTX_new()
flags=wolfSSL_EVP_CIPHER_CTX_flags(ctx);

parameterdescription.para:
パスワードコールバック Example WOLFSSL_BIO*bio;
WOLFSSL_EVP_PKEY*key;
intret;
//createbioandsetupkey
ret=wolfSSL_PEM_write_bio_PrivateKey(bio,key,NULL,NULL,0,NULL,NULL);
//checkretvalue

フォーマットで指定された形式で、WolfSSL SSLコンテキストにロードされるRSA秘密鍵を含むファイルの名前へのポインタ。 Example intret=0;
WOLFSSL_CTX*ctx;
...
ret=wolfSSL_CTX_use_RSAPrivateKey_file(ctx,“./server-key.pem”,
SSL_FILETYPE_PEM);
if(ret!=SSL_SUCCESS){
//errorloadingprivatekeyfile
}
...

wolfssl sslセッションにロードされる証明書を含むファイルの名前へのポインタは、フォーマットで指定された形式でフォーマットします。 Example intret=0;
WOLFSSL*ssl;
...
ret=wolfSSL_use_certificate_file(ssl,“./client-cert.pem”,
SSL_FILETYPE_PEM);
if(ret!=SSL_SUCCESS){
//errorloadingcertfile
}
...

detaileddescription.para:
SSL_SUCCESS 成功すると。 


SSL_FAILURE 関数呼び出しが失敗した場合、可能な原因には次のようになります。ファイルは誤った形式で、または「format」引数を使用して誤った形式が与えられていますが、ファイルは存在しません。メモリ不足状態が発生すると、ベース16のデコードがファイルで失敗し、キーファイルは暗号化されていますが、パスワードは提供されていません。 



ssl



wolfssl_new（）で作成されたwolfssl構造へのポインタ。 




file



wolfssl sslセッションにロードされるキーファイルを含むファイルの名前へのポインタは、フォーマットで指定された形式でフォーマットします。 Example intret=0;
WOLFSSL*ssl;
...
ret=wolfSSL_use_PrivateKey_file(ssl,“./server-key.pem”,
SSL_FILETYPE_PEM);
if(ret!=SSL_SUCCESS){
//errorloadingkeyfile
}
...





wolfSSL_CTX_use_PrivateKey_buffer 


wolfSSL_CTX_use_PrivateKey_file 


wolfSSL_use_PrivateKey_buffer 


wc_CryptoCb_RegisterDevice 


wolfSSL_SetDevId

If using an external key store and do not have the private key you can instead provide the public key and register the crypro callback to handle the signing. For this you can build with either build with crypto callbacks or PK callbacks. To enable crypto callbacks use enable-cryptocb or WOLF_CRYPTO_CB and register a crypto callback using wc_CryptoCb_RegisterDevice and set the associated devId using wolfSSL_SetDevId.

