ssl_new（）関数によって作成されたwolfssl構造体へのポインタ Example WOLFSSL*ssl;
WOLFSSL_CTX*ctx;
intret;
ctx=wolfSSL_CTX_new(wolfSSLv23_server_method());
ssl=wolfSSL_new(ctx);
ret=WolfSSL_set_tlsext_status_type(ssl,TLSEXT_STATUSTYPE_ocsp);
wolfSSL_free(ssl);
wolfSSL_CTX_free(ctx);

PKCS12バッファを読み取るためのWOLFSSL_BIO構造。 Example WC_PKCS12*pkcs;
WOLFSSL_BIO*bio;
WOLFSSL_X509*cert;
WOLFSSL_EVP_PKEY*pkey;
STACK_OF(X509)certs;
//bioloadsinPKCS12file
wolfSSL_d2i_PKCS12_bio(bio,&pkcs);
wolfSSL_PKCS12_parse(pkcs,“apassword”,&pkey,&cert,&certs)
wc_PKCS12_free(pkcs)
//usecert,pkey,andoptionallycertsstack

PKCS12バッファを書き込むためのWOLFSSL_BIO構造。 Example WC_PKCS12pkcs12;
FILE*f;
bytebuffer[5300];
charfile[]="./test.p12";
intbytes;
WOLFSSL_BIO*bio;
pkcs12=wc_PKCS12_new();
f=fopen(file,"rb");
bytes=(int)fread(buffer,1,sizeof(buffer),f);
fclose(f);
//converttheDERfileintoaninternalstructure
wc_d2i_PKCS12(buffer,bytes,pkcs12);
bio=wolfSSL_BIO_new(wolfSSL_BIO_s_mem());
//convertPKCS12structureintobio
wolfSSL_i2d_PKCS12_bio(bio,pkcs12);
wc_PKCS12_free(pkcs)
//usebio

PKCS12から復号された証明書を保持する構造 Example WC_PKCS12*pkcs;
WOLFSSL_BIO*bio;
WOLFSSL_X509*cert;
WOLFSSL_EVP_PKEY*pkey;
STACK_OF(X509)certs;
//bioloadsinPKCS12file
wolfSSL_d2i_PKCS12_bio(bio,&pkcs);
wolfSSL_PKCS12_parse(pkcs,“apassword”,&pkey,&cert,&certs)
wc_PKCS12_free(pkcs)
//usecert,pkey,andoptionallycertsstack
